export const neighborFrontages=[{"buildingId": 265936, "wallIndex": 0, "a": [121.56589228, 25.034925257, 8.360004068], "b": [121.566021775, 25.034923055, 8.360004068], "width": 13.0619, "height": 33.58, "endpointDistanceM": [0.11721947059200773, 0.25872420255703116]}, {"buildingId": 266115, "wallIndex": 3, "a": [121.566021775, 25.034923055, 8.360004068], "b": [121.566206307, 25.034919915, 8.360004068], "width": 18.6133, "height": 11.14, "endpointDistanceM": [0.25872420255703116, 0.02338356223175632]}, {"buildingId": 266138, "wallIndex": 4, "a": [121.565763353, 25.034971378, 8.360004068], "b": [121.565893383, 25.034968882, 8.360004068], "width": 13.1165, "height": 9.5, "endpointDistanceM": [0.05727732825834983, 0.10609952106163904]}];
export function isNeighborFrontage(building,wall){return neighborFrontages.some(f=>f.buildingId===building.id&&f.a.every((v,i)=>Math.abs(v-wall.a[i])<1e-8)&&f.b.every((v,i)=>Math.abs(v-wall.b[i])<1e-8));}
